function panel(id){if(id==='nawaf'){P.innerHTML='<div class="role">Founder / CEO</div><h3>نواف</h3><div class="meta"><div><span>الموقع</span><b>المكتب التنفيذي</b></div><div><span>الحالة</span><b>قيادة الشركة</b></div></div><div class="actions"><button class="primary" data-a="meeting">استدعاء الجميع</button><button data-a="work">إرجاع للعمل</button></div>';bind();return}selected=id;const e=E.find(x=>x.id===id),a=agents.get(id),t=tasks.find(x=>x.employeeId===id);P.innerHTML='<div class="role">'+e.role+'</div><h3>'+e.name+'</h3><div class="meta"><div><span>الحالة</span><b>'+(a.moving?'يتحرك':a.mode)+'</b></div><div><span>المهمة</span><b>'+(t?.title||'عمل القسم')+'</b></div></div><div class="actions"><button class="primary" data-a="nawaf">إلى نواف</button><button data-a="home">للمكتب</button><button data-a="focus">تركيز</button><button data-a="review">مراجعة</button></div>';bind()}
